/* Admin member workspace: uses the signed-in administrator and existing scoped reads. */
window.MioAdminMember={create(api){
 const {root,db,authorized,identity,esc,planName,countryOptions,countryBadge,safeImage,confirmSensitive,onClose,onSaved}=api;
 let member=null,record=null,owner=null,sequence=0,tab='dashboard',data={},errors={},busy=false,networkKind='generation',networkRootCode=null,networkSequence=0;
 const tabs=[['dashboard','Dashboard'],['profile','Profile'],['wallets','Wallets'],['network','Tree / Network'],['earnings','Earnings'],['packages','Packages'],['orders','Orders'],['transactions','Transactions']];
 const n=v=>Number(v||0).toLocaleString('en-PK',{maximumFractionDigits:4}),date=v=>v?new Date(v).toLocaleDateString('en-GB',{timeZone:'Asia/Karachi'}):'—';
 const $=s=>root.querySelector(s),valid=t=>authorized()&&identity()===owner&&t===sequence;
 async function result(q){const r=await q;if(r.error)throw r.error;return r.data;}
 async function all(table,fields,key,id){let rows=[];for(let start=0;;start+=1000){const page=await result(db.from(table).select(fields).eq(key,id).order('created_at').order('id').range(start,start+999));rows.push(...(page||[]));if(!page||page.length<1000)return rows;}}
 const card=(label,value,unit='')=>`<div class="dashboard-balance"><div><span>${esc(label)}</span><strong>${esc(value)} <small>${esc(unit)}</small></strong></div></div>`;
 const notice=key=>errors[key]?`<p role="alert" class="note warn">${esc(key)} could not load. ${esc(errors[key])} <button type="button" class="btn small" data-refresh>Retry</button></p>`:'';
 function table(headers,rows){return `<div class="table-wrap"><table class="admin-preview-table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(cell=>`<td>${esc(cell??'—')}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">No records.</td></tr>`}</tbody></table></div>`;}
 function walletCards(){const w=data.wallets;return notice('wallets')+(w?`<div class="admin-member-metrics">${card('Cash',n(w.cash),'MIO')}${card('Proceed',n(w.proceed),'MIO')}${card('Shopping',n(w.shopping),'points')}${card('Promotion',n(w.promotion),'points')}${card('Exchange',errors.exchange?'Unavailable':n(data.exchange),'MIO')}</div>`:'')+notice('exchange');}
 function profileView(){return `<div class="admin-member-profile-grid">${[['Full name',record.full_name],['MIO ID',record.member_code],['Email',member.email],['Phone',record.phone],['Country',api.countryName(record.country_code)],['Gender',record.gender],['Date of birth',record.date_of_birth?date(record.date_of_birth+'T12:00:00Z'):null],['Sponsor',member.sponsor_name],['Sponsor MIO ID',member.sponsor_code],['Status',record.status],['Joined',date(record.created_at)]].map(([label,value])=>`<div><small>${esc(label)}</small><strong>${esc(value||'—')}</strong></div>`).join('')}</div><button type="button" class="btn primary" data-edit-profile>Edit profile</button>`;}
 function dashboard(){const points=data.points||[],totals={};for(const p of points)totals[p.point_type]=(totals[p.point_type]||0)+Number(p.amount);const maintenance=data.maintenance||{};return `<section class="dashboard-identity"><div class="dashboard-person"><img src="${esc(safeImage(record.profile_photo_url)||'/assets/avatar-'+(['male','female'].includes(record.gender)?record.gender:'neutral')+'.svg')}" alt="Profile"><div><h1>${esc(record.full_name)}</h1><p>${esc(record.member_code)}</p>${countryBadge(record.country_code)}<small>Enrolled · ${date(record.created_at)}</small></div></div><div class="dashboard-package"><div><small>Current membership</small><strong>${esc(planName(data.wallets?.package_code||member.package_code))}</strong><span class="dashboard-status ${record.status==='active'?'active':''}">${esc(record.status)}</span><p>Rank · ${esc(member.rank_name||record.achieved_rank||'Unranked')}</p></div></div></section>${walletCards()}<section class="dashboard-panel"><h3>Points & qualification</h3>${notice('points')}<div class="admin-member-metrics">${Object.entries(totals).map(([key,value])=>card(key,n(value),'points')).join('')||'<p>No point activity.</p>'}</div></section><section class="dashboard-panel"><h3>Maintenance</h3>${notice('maintenance')}<div class="admin-member-profile-grid"><div><small>Monthly due</small><strong>${date(maintenance.monthly_due_at)}</strong></div><div><small>Annual due</small><strong>${date(maintenance.annual_due_at)}</strong></div><div><small>Monthly shopping progress</small><strong>${n(maintenance.monthly_progress_ppv)} PPV</strong></div></div></section><section class="dashboard-panel"><h3>Earnings summary</h3>${earningsSummary()}</section>`;}
 function earningsSummary(){const totals=new Map();for(const b of data.earnings||[]){const key=(b.currency||'MIO')+' · '+(b.status||'Unknown');totals.set(key,(totals.get(key)||0)+Number(b.payable_amount));}return notice('earnings')+`<div class="admin-member-metrics">${[...totals].map(([k,v])=>card(k,n(v))).join('')||'<p>No earnings recorded.</p>'}</div>`;}
 function render(){if(!record||!authorized()||identity()!==owner)return;root.innerHTML=`<header class="admin-member-banner"><div><small>ADMIN · MEMBER VIEW</small><strong>${esc(record.full_name)} <span>${esc(record.member_code)}</span></strong></div><button class="btn" type="button" data-refresh>Refresh</button><button class="btn" type="button" data-back>Back to Account Holders</button></header><div class="admin-member-shell"><aside class="admin-member-nav" aria-label="Member dashboard sections">${tabs.map(([key,title])=>`<button type="button" data-member-tab="${key}" aria-current="${tab===key?'page':'false'}">${esc(title)}</button>`).join('')}</aside><div class="admin-member-content"><h2 tabindex="-1">${tabs.find(t=>t[0]===tab)?.[1]}</h2><div data-member-content></div></div></div>`;let html='';if(tab==='dashboard')html=dashboard();if(tab==='profile')html=profileView();if(tab==='wallets')html=walletCards();if(tab==='earnings')html=earningsSummary()+table(['Date','Bonus','Generation','Amount','Currency','Status'],(data.earnings||[]).slice().reverse().map(b=>[date(b.created_at),b.method,b.generation,n(b.payable_amount),b.currency,b.status]));if(tab==='packages')html=notice('packages')+table(['Package','Activated','Status','Base value'],(data.packages||[]).map(p=>[planName(p.package_code),date(p.activated_at),p.status,n(p.base_value)]));if(tab==='network')html=`<div class="admin-member-network-tabs">${[['generation','Generation'],['binary','Binary'],['single_line','Placement']].map(([key,label])=>`<button class="btn ${networkKind===key?'primary':''}" data-network-view="${key}" type="button">${label}</button>`).join('')}</div><div data-member-network>Loading network…</div>`;if(tab==='orders')html=notice('orders')+table(['Order','Date','Status','Payment','Total PKR'],(data.orders||[]).slice().reverse().map(o=>[o.order_code,date(o.created_at),o.status,o.payment_status,n(o.total_pkr)]));if(tab==='transactions')html=notice('transactions')+table(['Date','Action','Amount MIO','Reason'],(data.transactions||[]).slice().reverse().map(r=>[date(r.created_at),r.action,n(r.amount),r.reason]));$('[data-member-content]').innerHTML=html;if(tab==='network')loadNetwork();}
 async function loadNetwork(){const t=sequence,turn=++networkSequence,kind=networkKind;try{const value=await result(db.rpc('my_network_identity',{p_kind:kind,p_root_code:networkRootCode||record.member_code,p_depth:4}));if(!valid(t)||tab!=='network'||kind!==networkKind||turn!==networkSequence)return;const nodes=value?.nodes||[];$('[data-member-network]').innerHTML=`<p>Selected member’s ${esc(kind.replaceAll('_',' '))} tree · first 4 levels. Select a member to explore their branch.</p><div class="admin-member-tree">${nodes.map(node=>`<button type="button" class="admin-member-node" data-network-root="${esc(node.member_code)}"><small>Level ${Number(node.level??node.depth??0)} · ${esc(node.side||'')}</small><strong>${esc(node.full_name||'Member')}</strong><span>${esc(node.member_code)}</span><small>${esc(planName(node.package||node.package_code))} · ${esc(node.status||'')}</small></button>`).join('')||'<p>No members in this network.</p>'}</div><button type="button" class="btn" data-network-reset>Return to selected member</button>`;}catch(e){if(valid(t)&&tab==='network')$('[data-member-network]').textContent='Could not load network: '+e.message;}}
 async function open(row){if(!authorized())throw Error('Admin access required');owner=identity();member={...row};record=null;data={};errors={};tab='dashboard';networkRootCode=null;root.hidden=false;const t=++sequence;root.innerHTML='<p role="status">Loading member dashboard…</p>';try{const p=await result(db.from('member_profiles').select('user_id,member_code,full_name,phone,country_code,gender,date_of_birth,sponsor_id,status,created_at,achieved_rank,profile_photo_url').eq('user_id',row.user_id).maybeSingle());if(!valid(t))return;if(!p)throw Error('Member not found or access unavailable');record=p;const tasks={wallets:()=>result(db.rpc('admin_network_control_members',{p_offset:0,p_limit:100,p_package:null,p_search:p.member_code})).then(r=>{const w=r?.rows?.find(x=>x.member_id===p.user_id);if(!w)throw Error('Member wallet record unavailable');return w;}),exchange:()=>result(db.rpc('admin_network_control_exchange',{p_offset:0,p_limit:100,p_search:p.member_code})).then(r=>r?.rows?.find(x=>x.member_id===p.user_id)?.exchange??0),points:()=>all('point_ledger','id,point_type,amount,created_at','member_id',p.user_id),earnings:()=>all('bonus_transactions','id,method,payable_amount,currency,status,generation,created_at','beneficiary_id',p.user_id),packages:()=>result(db.from('package_activations').select('package_code,activated_at,status,base_value').eq('member_id',p.user_id).order('activated_at',{ascending:false})),maintenance:()=>result(db.from('member_maintenance').select('monthly_due_at,annual_due_at,monthly_progress_ppv').eq('member_id',p.user_id).maybeSingle()),orders:()=>all('orders','id,order_code,created_at,status,payment_status,total_pkr','buyer_id',p.user_id),transactions:()=>all('mio_ledger','id,amount,action,reason,created_at','member_id',p.user_id)};await Promise.all(Object.entries(tasks).map(async([key,fn])=>{try{const value=await fn();if(valid(t))data[key]=value;}catch(e){if(valid(t))errors[key]=e.message;}}));if(valid(t))render();}catch(e){if(valid(t)){root.innerHTML=`<p role="alert">${esc(e.message)}</p><button class="btn" type="button" data-refresh>Retry</button><button class="btn" type="button" data-back>Back to Account Holders</button>`;}}}
 function edit(){const p=record;$('[data-member-content]').innerHTML=`<form class="form admin-member-edit"><label>Full name<input name="full_name" required minlength="2" maxlength="150" value="${esc(p.full_name)}"></label><label>Phone<input name="phone" required minlength="5" maxlength="40" value="${esc(p.phone||'')}"></label><label>Country<select name="country" required>${countryOptions(p.country_code)}</select></label><label>Gender<select name="gender"><option value="">Not set</option><option value="male">Male</option><option value="female">Female</option></select></label><label>Date of birth<input type="date" name="dob" min="1900-01-01" max="${new Date().toISOString().slice(0,10)}" value="${esc(p.date_of_birth||'')}"></label><label>Reason for change<textarea name="reason" minlength="10" maxlength="2000" required></textarea></label><p data-save-status role="status"></p><div><button type="submit" class="btn primary">Verify & Save</button> <button type="button" class="btn" data-cancel-edit>Cancel</button></div></form>`;$('[name="gender"]').value=p.gender||'';$('[name="full_name"]').focus();}
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-back')){clear();onClose();return;}if(!authorized()||identity()!==owner)return;if(b.hasAttribute('data-refresh')){if(member)open(member);return;}if(b.dataset.memberTab){tab=b.dataset.memberTab;render();}if(b.hasAttribute('data-edit-profile'))edit();if(b.hasAttribute('data-cancel-edit'))render();if(b.dataset.networkView){networkKind=b.dataset.networkView;networkRootCode=null;render();}if(b.dataset.networkRoot){networkRootCode=b.dataset.networkRoot;loadNetwork();}if(b.hasAttribute('data-network-reset')){networkRootCode=null;loadNetwork();}});
 root.addEventListener('submit',async e=>{if(!e.target.matches('.admin-member-edit'))return;e.preventDefault();const form=e.target;if(busy||!authorized()||identity()!==owner||!form.reportValidity())return;busy=true;const t=sequence,id=record.user_id,button=form.querySelector('[type="submit"]'),status=form.querySelector('[data-save-status]');button.disabled=true;try{const payload={p_member_id:id,p_name:form.elements.full_name.value.trim(),p_phone:form.elements.phone.value.trim(),p_country:form.elements.country.value,p_gender:form.elements.gender.value||null,p_date_of_birth:form.elements.dob.value||null,p_reason:form.elements.reason.value.trim()};await confirmSensitive('Save profile changes for '+record.member_code);if(!valid(t))return;await result(db.rpc('admin_save_member_profile',payload));if(!valid(t))return;await open({...member,full_name:payload.p_name,phone:payload.p_phone,country_code:payload.p_country});tab='profile';render();$('[data-member-content]').insertAdjacentHTML('afterbegin','<p role="status" class="note">Profile saved successfully.</p>');onSaved();}catch(e){if(valid(t))status.textContent='Could not save: '+e.message;}finally{busy=false;button.disabled=false;}});
 function clear(){sequence++;member=null;record=null;data={};errors={};owner=null;root.replaceChildren();root.hidden=true;}
 return {open,clear};
}};
